typedef long long ll;

typedef struct {
    int *data;
    int size;
    int cap;
} Vec;

static void vec_init(Vec *v) {
    v->data = NULL;
    v->size = 0;
    v->cap = 0;
}

static void vec_push(Vec *v, int x) {
    if (v->size == v->cap) {
        v->cap = v->cap ? v->cap * 2 : 4;
        v->data = (int *)realloc(v->data, sizeof(int) * v->cap);
    }
    v->data[v->size++] = x;
}

typedef struct {
    int *parent;
    int *sz;
} DSU;

static void dsu_init(DSU *d, int n) {
    d->parent = (int *)malloc(sizeof(int) * n);
    d->sz = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
        d->parent[i] = i;
        d->sz[i] = 1;
    }
}

static int dsu_find(DSU *d, int x) {
    if (d->parent[x] == x) return x;
    d->parent[x] = dsu_find(d, d->parent[x]);
    return d->parent[x];
}

static void dsu_unite(DSU *d, int a, int b) {
    a = dsu_find(d, a);
    b = dsu_find(d, b);
    if (a == b) return;
    if (d->sz[a] < d->sz[b]) {
        int t = a; a = b; b = t;
    }
    d->parent[b] = a;
    d->sz[a] += d->sz[b];
}

static int dsu_size(DSU *d, int x) {
    return d->sz[dsu_find(d, x)];
}

int main(void) {
    int N, M, K;
    scanf("%d %d %d", &N, &M, &K);

    DSU dsu;
    dsu_init(&dsu, N);

    int *friend_cnt = (int *)calloc(N, sizeof(int));
    Vec *blocks = (Vec *)malloc(sizeof(Vec) * N);
    for (int i = 0; i < N; i++) vec_init(&blocks[i]);

    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        a--; b--;
        friend_cnt[a]++;
        friend_cnt[b]++;
        dsu_unite(&dsu, a, b);
    }

    for (int i = 0; i < K; i++) {
        int c, d;
        scanf("%d %d", &c, &d);
        c--; d--;
        vec_push(&blocks[c], d);
        vec_push(&blocks[d], c);
    }

    int *ans = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) {
        ans[i] = dsu_size(&dsu, i) - 1 - friend_cnt[i];
    }

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < blocks[i].size; j++) {
            int b = blocks[i].data[j];
            if (dsu_find(&dsu, i) == dsu_find(&dsu, b)) {
                ans[i]--;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    }
    printf("\n");

    return 0;
}

