        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken()) - 1;
            int b = Integer.parseInt(st.nextToken()) - 1;
            friendEdges.add(new int[]{a, b});
            friendCount[a]++;
            friendCount[b]++;
            union(parent, size, a, b);
        }

        // block relationships
        int[] blockCount = new int[N];
        List<int[]> blockEdges = new ArrayList<>();
        for (int i = 0; i < K; i++) {
            st = new StringTokenizer(br.readLine());
            int c = Integer.parseInt(st.nextToken()) - 1;
            int d = Integer.parseInt(st.nextToken()) - 1;
            blockEdges.add(new int[]{c, d});
        }

        // Now compute candidates: componentSize - 1 - directFriendsInComponent - blockedInComponent
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            int compSize = size[find(parent, i)];
            int candidates = compSize - 1 - friendCount[i];

            // subtract blocked users in same component
            for (int[] block : blockEdges) {
                int u = block[0], v = block[1];
                if (u == i && find(parent, v) == find(parent, i)) {
                    candidates--;
                }
                if (v == i && find(parent, u) == find(parent, i)) {
                    candidates--;
                }
            }
            sb.append(candidates).append(" ");
        }

        System.out.println(sb.toString().trim());
    }

    static int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    static void union(int[] parent, int[] size, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra != rb) {
            if (size[ra] < size[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }
    }
}

