public class Main {
    static int[] parent, rank;

    static int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void union(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return;
        if (rank[px] < rank[py]) { int t = px; px = py; py = t; }
        parent[py] = px;
        if (rank[px] == rank[py]) rank[px]++;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        parent = new int[N + 1];
        rank = new int[N + 1];
        for (int i = 1; i <= N; i++) parent[i] = i;

        // Store friendships
        Set<Long>[] friends = new HashSet[N + 1];
        for (int i = 1; i <= N; i++) friends[i] = new HashSet<>();

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            union(a, b);
            friends[a].add((long)b);
            friends[b].add((long)a);
        }

        // Store blockships
        Set<Long>[] blocked = new HashSet[N + 1];
        for (int i = 1; i <= N; i++) blocked[i] = new HashSet<>();

        for (int i = 0; i < K; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            blocked[a].add((long)b);
            blocked[b].add((long)a);
        }

        // Count component sizes
        Map<Integer, Integer> compSize = new HashMap<>();
        for (int i = 1; i <= N; i++) {
            int p = find(i);
            compSize.put(p, compSize.getOrDefault(p, 0) + 1);
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= N; i++) {
            int p = find(i);
            int sameComp = compSize.get(p);
            // Candidates = same component - self - direct friends in same comp - blocked in same comp
            // But we need to be careful: direct friends are by definition in same component
            // Blocked people might or might not be in same component

            int directFriends = friends[i].size(); // all in same component

            // Count blocked people in same component
            int blockedInComp = 0;
            for (long b : blocked[i]) {
                if (find((int)b) == p) blockedInComp++;
            }

            int candidates = sameComp - 1 - directFriends - blockedInComp;
            sb.append(candidates).append("\n");
        }

        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class DSU {
        int[] parent;
        int[] size;

        DSU(int n) {
            parent = new int[n];
            size = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            if (parent[x] == x) return x;
            return parent[x] = find(parent[x]);
        }

        void union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return;
            if (size[ra] < size[rb]) {
                int t = ra;
                ra = rb;
                rb = t;
            }
            parent[rb] = ra;
            size[ra] += size[rb];
        }

        int componentSize(int x) {
            return size[find(x)];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int M = fs.nextInt();
        int K = fs.nextInt();

        DSU dsu = new DSU(N);
        int[] friendCount = new int[N];
        int[][] friends = new int[M][2];

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            friends[i][0] = a;
            friends[i][1] = b;
            friendCount[a]++;
            friendCount[b]++;
            dsu.union(a, b);
        }

        int[] blockCountInSameComponent = new int[N];
        int[][] blocks = new int[K][2];
        for (int i = 0; i < K; i++) {
            int c = fs.nextInt() - 1;
            int d = fs.nextInt() - 1;
            blocks[i][0] = c;
            blocks[i][1] = d;
        }

        for (int i = 0; i < K; i++) {
            int c = blocks[i][0];
            int d = blocks[i][1];
            if (dsu.find(c) == dsu.find(d)) {
                blockCountInSameComponent[c]++;
                blockCountInSameComponent[d]++;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            int ans = dsu.componentSize(i) - 1 - friendCount[i] - blockCountInSameComponent[i];
            if (i > 0) sb.append(' ');
            sb.append(ans);
        }
        System.out.println(sb);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
